import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");

/**
 * Extract the inner `(require) => { ... }` factory from a DSH client bundle
 * wrapped in `window.__ModuleLoader__.load({ id: ..., factory: ... });`.
 */
function extractClientFactory(source, label) {
  const marker = "factory:";
  const idx = source.indexOf(marker);
  if (idx === -1) {
    throw new Error(`Could not locate "factory:" in ${label}`);
  }
  const start = source.indexOf("(", idx + marker.length);
  if (start === -1) {
    throw new Error(`Could not locate factory function start in ${label}`);
  }
  // Strip trailing `});` (and optional sourceMappingURL comment)
  let trimmed = source.replace(/\/\/#\s*sourceMappingURL=.*$/m, "").trimEnd();
  if (trimmed.endsWith(";")) trimmed = trimmed.slice(0, -1).trimEnd();
  if (!trimmed.endsWith(")")) {
    throw new Error(`Unexpected end of client bundle in ${label}`);
  }
  trimmed = trimmed.slice(0, -1).trimEnd(); // remove closing `)` of load(...)
  if (!trimmed.endsWith("}")) {
    throw new Error(`Unexpected end of load options object in ${label}`);
  }
  trimmed = trimmed.slice(0, -1).trimEnd(); // remove closing `}` of { id, factory }
  return trimmed.slice(start);
}

const CLIENT_COMPONENTS = [
  {
    id: "subscriptions",
    path: join(root, "components", "subscriptions", "lib", "client.js"),
    kind: "bundle",
  },
  {
    id: "thinking-provider",
    path: join(root, "components", "thinking-provider", "lib", "client.js"),
    kind: "bundle",
  },
  {
    id: "general-configs",
    path: join(root, "src", "client", "general-configs-client.js"),
    kind: "inline-factory",
    factoryFn: "createGeneralConfigsClient",
  },
];

export function buildClientBundle() {
  const toolkitClientSrc = readFileSync(join(root, "src", "client", "toolkit-client.js"), "utf8");

  const inlineSources = [];
  const factoryEntries = CLIENT_COMPONENTS.map((entry) => {
    const raw = readFileSync(entry.path, "utf8");
    if (entry.kind === "inline-factory") {
      inlineSources.push(raw);
      return `  ${JSON.stringify(entry.id)}: ${entry.factoryFn}`;
    }
    const factory = extractClientFactory(raw, entry.id);
    return `  ${JSON.stringify(entry.id)}: ${factory}`;
  });

  return `// Auto-generated by scripts/build.mjs — do not edit directly.
window.__ModuleLoader__.load({ id: "spig-dsh-toolkit", factory: (require) => {
var module = { exports: {} };
var exports = module.exports;

${toolkitClientSrc}

${inlineSources.join("\n\n")}

const TOOLKIT_CLIENT_FACTORIES = {
${factoryEntries.join(",\n")}
};

const toolkitExports = createToolkitClient(require, TOOLKIT_CLIENT_FACTORIES);
exports.name = toolkitExports.name;
exports.inject = toolkitExports.inject;
exports.apply = toolkitExports.apply;
module.exports = exports;
return module.exports;
} });
`;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === join(process.argv[1]);
if (isMain) {
  const output = buildClientBundle();
  const outPath = join(root, "lib", "client.js");
  if (process.argv.includes("--check")) {
    const current = readFileSync(outPath, "utf8");
    if (current !== output) {
      console.error(`[spig-dsh-toolkit] lib/client.js is out of sync with client sources. Run "npm run build".`);
      process.exit(1);
    }
    console.log(`[spig-dsh-toolkit] lib/client.js is up to date (${output.length} bytes)`);
  } else {
    writeFileSync(outPath, output, "utf8");
    console.log(`[spig-dsh-toolkit] built ${outPath} (${output.length} bytes, ${CLIENT_COMPONENTS.length} client components)`);
  }
}
